window.SLIDE_DECKS["banco-de-dados/aula-02"] = {
  title: "Modelagem Conceitual de Dados I e Prática no brModelo",
  slides: [
  "<section class=\"slide slide-cover active\">\n      <div class=\"section-tag\">Modelagem Conceitual de Dados &bull; Aula 02</div>\n      <h1 class=\"cover-title\">BANCO DE DADOS I</h1>\n      <p class=\"slide-subtitle\" style=\"font-size: 1.25rem; max-width: 820px; margin-bottom: 25px;\">\n        Modelagem Conceitual I — Abordagem Entidade-Relacionamento (DER Básico), Cardinalidades e Prática no brModelo\n      </p>\n\n      <div style=\"display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-bottom: 30px;\">\n        <span class=\"badge badge-red\">Fatec Sorocaba</span>\n        <span class=\"badge badge-gray\">CST em Análise e Desenvolvimento de Sistemas</span>\n        <span class=\"badge badge-gray\">1º Semestre &bull; Matriz R-11</span>\n        <span class=\"badge badge-blue\">Prof. André Souza</span>\n        <span class=\"badge badge-green\">Presencial (Sala &amp; Lab)</span>\n      </div>\n\n      <div class=\"callout\" style=\"max-width: 800px; text-align: left;\">\n        <strong>Dinâmica de hoje (4 Aulas):</strong> 2 aulas de teoria e fundamentos em sala de aula (Retrospectiva Biblioteca Saber, Tipologia de Atributos, Entidades Fracas e Cardinalidades) seguidas de 2 horas de prática guiada no brModelo em laboratório de informática.\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Organização do encontro &bull; 3h20</div>\n      <h2 class=\"slide-title\">Roteiro Integrado da Aula 02</h2>\n      <p class=\"slide-subtitle\">A aula combina revisão dos conceitos, análise de requisitos e construção de modelos no laboratório.</p>\n\n      <div class=\"stepper\">\n        <div class=\"step-item\">\n          <div class=\"step-circle\">1</div>\n          <div class=\"step-title\">Correção &amp; Nivelamento</div>\n          <div class=\"step-desc\">30 min &bull; Sala de Aula</div>\n        </div>\n        <div class=\"step-item\">\n          <div class=\"step-circle\">2</div>\n          <div class=\"step-title\">Teoria Avançada DER</div>\n          <div class=\"step-desc\">50 min &bull; Sala de Aula</div>\n        </div>\n        <div class=\"step-item\">\n          <div class=\"step-circle\">3</div>\n          <div class=\"step-title\">Ambiente brModelo</div>\n          <div class=\"step-desc\">30 min &bull; Laboratório</div>\n        </div>\n        <div class=\"step-item\">\n          <div class=\"step-circle\">4</div>\n          <div class=\"step-title\">Prática &amp; Oficina</div>\n          <div class=\"step-desc\">70 min &bull; Laboratório</div>\n        </div>\n      </div>\n\n      <div class=\"grid-2\" style=\"margin-top: 24px;\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Parte 1 — Sala de Aula (2 Aulas Teóricas)</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.88rem; line-height: 1.7; padding-left: 18px;\">\n            <li>Correção comentada da <em>Biblioteca Saber</em> (Fixação da Aula 01).</li>\n            <li>Tipos de atributos: simples, compostos, multivalorados e derivados.</li>\n            <li>Entidades fortes vs. fracas e dependência existencial.</li>\n            <li>Leitura das cardinalidades mínimas e máximas.</li>\n          </ul>\n        </div>\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">Parte 2 — Laboratório (2 Horas de Prática)</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.88rem; line-height: 1.7; padding-left: 18px;\">\n            <li>Apresentação da ferramenta CASE <strong>brModelo</strong>.</li>\n            <li>Prática guiada passo a passo: <em>Controle Comercial Sorocaba</em>.</li>\n            <li>Atributos de transação em relacionamentos N:N.</li>\n            <li>Atividade prática autônoma individual / em duplas com suporte circulante.</li>\n          </ul>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Bloco 1 &bull; Retrospectiva da Aula 01</div>\n      <h2 class=\"slide-title\">Correção do Estudo de Caso: Biblioteca Saber</h2>\n      <p class=\"slide-subtitle\">Análise semântica dos requisitos do catálogo de livros propostos na primeira aula.</p>\n\n      <div class=\"card card-red\" style=\"padding: 22px; font-size: 1.05rem; line-height: 1.8;\">\n        <p>\n          <em>\"A Biblioteca Municipal <strong>Saber</strong> deseja informatizar o catálogo de livros. Cada <strong>livro</strong> possui um <strong>código</strong> identificador, o <strong>título</strong> da obra e o <strong>ano de publicação</strong>.</em>\n        </p>\n        <p style=\"margin-top: 10px;\">\n          <em>Cada livro é publicado por exatamente uma <strong>editora</strong>. De cada editora, são registrados o <strong>código</strong> de identificação, a <strong>razão social</strong> e a <strong>cidade</strong> sede. Uma editora pode publicar múltiplos livros cadastrados no acervo da biblioteca.\"</em>\n        </p>\n      </div>\n\n      <div class=\"callout callout-blue\" style=\"margin-top: 20px;\">\n        <strong>Meta desta correção:</strong> Aplicar o método de cinco etapas para verificar a identificação das entidades, o mapeamento dos atributos identificadores e a definição precisa das cardinalidades mínimas e máximas.\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Bloco 1 &bull; Correção comentada</div>\n      <h2 class=\"slide-title\">Etapas 2 e 3: Elementos e Regras de Negócio</h2>\n      <p class=\"slide-subtitle\">Identificação de entidades, atributos, relacionamentos e regras a partir do enunciado.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Etapa 2: Identificação dos Elementos</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.9rem; line-height: 1.8; padding-left: 18px;\">\n            <li><strong>Entidades:</strong> <code>LIVRO</code> e <code>EDITORA</code>.</li>\n            <li><strong>Atributos de LIVRO:</strong> <span style=\"color: var(--cps-red); font-weight: 600;\">cod_livro (identificador)</span>, titulo, ano_pub.</li>\n            <li><strong>Atributos de EDITORA:</strong> <span style=\"color: var(--cps-red); font-weight: 600;\">cod_editora (identificador)</span>, razao_social, cidade.</li>\n            <li><strong>Relacionamento Semântico:</strong> <code>PUBLICA</code> (ou <code>PUBLICADO_POR</code>).</li>\n          </ul>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">Etapa 3: Regras e Cardinalidades</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.9rem; line-height: 1.8; padding-left: 18px;\">\n            <li><strong>LIVRO para EDITORA:</strong> Todo livro é publicado obrigatoriamente por <strong>exatamente 1</strong> editora &rarr; <strong>(1, 1)</strong>.</li>\n            <li><strong>EDITORA para LIVRO:</strong> Uma editora parceira pode ter sido cadastrada sem ter livros ainda, ou possuir muitos &rarr; <strong>(0, N)</strong>.</li>\n            <li><strong>Classificação:</strong> Relacionamento binário de cardinalidade máxima <strong>1:N</strong>, com participação obrigatória do Livro e opcional da Editora.</li>\n          </ul>\n        </div>\n      </div>\n\n      <div class=\"callout callout-green\" style=\"margin-top: 18px;\">\n        <strong>Como interpretar:</strong> A cardinalidade máxima indica quantas ocorrências podem ser associadas. A mínima indica se a participação é opcional (0) ou obrigatória (1).\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Bloco 1 &bull; Correção comentada</div>\n      <h2 class=\"slide-title\">Etapas 4 e 5: DER Completo na Notação Chen</h2>\n      <p class=\"slide-subtitle\">Representação gráfica formal do caso Biblioteca Saber construída segundo o padrão clássico.</p>\n\n      <div class=\"diagram-container\">\n        <img src=\"../Banco de Dados I/slides/img/der_editora.png\" alt=\"DER Notação Chen — Estudo de Caso Biblioteca Saber\" class=\"diagram-img\">\n      </div>\n\n      <div class=\"callout\" style=\"margin-top: 16px;\">\n        <strong>Simbologia Chen no diagrama:</strong> Retângulos representam entidades, Losangos representam associações semânticas e Elipses representam atributos. O círculo preenchido destaca o atributo identificador unívoco.\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Bloco 1 &bull; Análise Semântica</div>\n      <h2 class=\"slide-title\">Reflexão: Por que a Editora é (0, N) e não (1, N)?</h2>\n      <p class=\"slide-subtitle\">A cardinalidade mínima define se é possível cadastrar uma editora antes de associar livros a ela.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Cenário A: Se a Editora fosse (1, N) &bull; Obrigatória</div>\n          <p class=\"card-desc\">Significaria que uma editora <strong>só poderia existir no sistema se já tivesse pelo menos 1 livro cadastrado</strong> no mesmo instante.</p>\n          <div class=\"code-box\" style=\"margin-top: 10px; font-size: 0.82rem; color: #dc2626;\">\n            Com mínimo 1, a editora só poderia ser cadastrada junto com ao menos um livro.\n          </div>\n        </div>\n\n        <div class=\"card card-green\">\n          <div class=\"card-title\">Cenário B: Editora como (0, N) &bull; Opcional</div>\n          <p class=\"card-desc\">Significa que a editora pode ser pré-cadastrada como entidade autônoma no banco, antes mesmo da chegada física dos exemplares.</p>\n          <div class=\"code-box\" style=\"margin-top: 10px; font-size: 0.82rem; color: #16a34a;\">\n            Com mínimo 0, é possível cadastrar a editora antes de registrar seus livros.\n          </div>\n        </div>\n      </div>\n\n      <div class=\"callout callout-blue\" style=\"margin-top: 18px;\">\n        <strong>Regra de modelagem:</strong> As cardinalidades devem representar os requisitos confirmados com a organização.\n      </div>\n    </section>",
  "<section class=\"slide slide-cover\">\n      <div class=\"section-tag\">Bloco 2 &bull; Teoria em Sala de Aula</div>\n      <h2 class=\"cover-title\" style=\"font-size: 2.5rem;\">Tipologia Completa de Atributos &amp; Entidades Fracas</h2>\n      <p class=\"slide-subtitle\" style=\"max-width: 780px;\">\n        Aprofundando os conceitos do MER: atributos atômicos, compostos, multivalorados, derivados, identificadores e entidades dependentes.\n      </p>\n      <div class=\"callout\" style=\"max-width: 760px; text-align: left;\">\n        <strong>Objetivo das próximas seções:</strong> Compreender como a modelagem conceitual lida com estruturas de dados ricas antes de abrir o brModelo no laboratório.\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Fundamentação Teórica &bull; Atributos</div>\n      <h2 class=\"slide-title\">Atributos Simples (Atômicos) vs. Compostos</h2>\n      <p class=\"slide-subtitle\">A granularidade da informação determina o poder de busca, indexação e ordenação do banco.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">1. Atributo Simples / Atômico</div>\n          <p class=\"card-desc\">Valor indivisível na ótica do sistema de informação. Não possui subpartes com significado independente.</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.85rem; line-height: 1.6; padding-left: 16px; margin-top: 8px;\">\n            <li><code>cpf</code>: Sequência numérica única de 11 dígitos.</li>\n            <li><code>preco_unitario</code>: Valor numérico monetário atômico.</li>\n            <li><code>sigla_uf</code>: Código federativo de dois caracteres (ex.: 'SP').</li>\n          </ul>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">2. Atributo Composto</div>\n          <p class=\"card-desc\">Composto por múltiplos subatributos hierárquicos que possuem significado e uso próprios.</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.85rem; line-height: 1.6; padding-left: 16px; margin-top: 8px;\">\n            <li><code>Endereco</code> subdividido em:\n              <ul style=\"padding-left: 16px;\">\n                <li><code>logradouro</code> ('Av. Engenheiro Carlos Reinaldo Mendes')</li>\n                <li><code>numero</code> ('2015') &bull; <code>complemento</code> ('Bloco A')</li>\n                <li><code>bairro</code> ('Alto da Boa Vista') &bull; <code>cep</code> ('18013-280')</li>\n                <li><code>cidade</code> ('Sorocaba')</li>\n              </ul>\n            </li>\n          </ul>\n        </div>\n      </div>\n\n      <div class=\"callout callout-blue\" style=\"margin-top: 16px;\">\n        <strong>Impacto em SQL:</strong> Se você guardar o endereço inteiro em uma única coluna texto, como o sistema conseguirá fazer <code>WHERE cidade = 'Sorocaba'</code> ou ordenar os clientes por bairro? Não conseguirá sem custos absurdos de processamento!\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Fundamentação Teórica &bull; Atributos</div>\n      <h2 class=\"slide-title\">Atributos Monovalorados vs. Multivalorados</h2>\n      <p class=\"slide-subtitle\">Como representar situações em que uma entidade possui uma lista de valores para a mesma propriedade?</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">1. Atributo Monovalorado</div>\n          <p class=\"card-desc\">Armazena <strong>um único valor</strong> para cada ocorrência da entidade.</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.85rem; line-height: 1.6; padding-left: 16px; margin-top: 8px;\">\n            <li><code>data_nascimento</code>: data de nascimento de uma pessoa.</li>\n            <li><code>cnpj</code>: Uma empresa possui um único registro nacional.</li>\n            <li><code>peso_kg</code>: Medida atual aferida de um paciente.</li>\n          </ul>\n          <div class=\"code-box\" style=\"margin-top: 10px; font-size: 0.8rem;\">\n            Notação Chen: Elipse simples conectada à entidade.\n          </div>\n        </div>\n\n        <div class=\"card card-green\">\n          <div class=\"card-title\">2. Atributo Multivalorado</div>\n          <p class=\"card-desc\">Pode assumir um <strong>conjunto/lista de múltiplos valores</strong> para a mesma ocorrência.</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.85rem; line-height: 1.6; padding-left: 16px; margin-top: 8px;\">\n            <li><code>telefones</code>: Um cliente possui celular comercial, residencial e recado.</li>\n            <li><code>habilidades</code>: Um desenvolvedor domina Java, Python e SQL.</li>\n            <li><code>idiomas</code>: Um professor fala Português, Inglês e Espanhol.</li>\n          </ul>\n          <div class=\"code-box\" style=\"margin-top: 10px; font-size: 0.8rem;\">\n            Notação Chen: Elipse dupla contornada (( Atributo )).\n          </div>\n        </div>\n      </div>\n\n      <div class=\"callout callout-blue\" style=\"margin-top: 16px;\">\n        <strong>Atenção no Modelo Relacional:</strong> Na 1ª Forma Normal (1FN), tabelas relacionais proíbem colunas multivaloradas (ex.: salvar '1599123; 153221' na mesma célula). No modelo lógico, todo atributo multivalorado se tornará uma tabela satélite!\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Fundamentação Teórica &bull; Atributos</div>\n      <h2 class=\"slide-title\">Atributos Derivados e Identificadores (Chaves)</h2>\n      <p class=\"slide-subtitle\">Identificação de ocorrências e cálculo de valores derivados.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-amber\">\n          <div class=\"card-title\">1. Atributo Derivado (Calculado)</div>\n          <p class=\"card-desc\">Pode ser calculado a partir de outros atributos. O armazenamento depende dos requisitos de implementação.</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.85rem; line-height: 1.6; padding-left: 16px; margin-top: 8px;\">\n            <li><code>idade</code>: Calculada a partir de <code>(SYSDATE - data_nascimento)</code>.</li>\n            <li><code>total_pedido</code>: Somatório de <code>(quantidade * preco_venda)</code> dos itens.</li>\n            <li><code>anos_de_empresa</code>: Calculado a partir de <code>data_admissao</code>.</li>\n          </ul>\n          <div class=\"code-box\" style=\"margin-top: 10px; font-size: 0.8rem;\">\n            Notação Chen: Elipse com linha tracejada (- Atributo -).\n          </div>\n        </div>\n\n        <div class=\"card card-red\">\n          <div class=\"card-title\">2. Atributo Identificador (Chave)</div>\n          <p class=\"card-desc\">Propriedade cujos valores são estritamente exclusivos, identificando de modo inequívoco cada instância da entidade.</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.85rem; line-height: 1.6; padding-left: 16px; margin-top: 8px;\">\n            <li><code>id_cliente</code>: Código sequencial gerado pelo sistema.</li>\n            <li><code>numero_chassi</code>: Identificador físico universal de veículos.</li>\n            <li><code>isbn</code>: Código padrão internacional de publicações.</li>\n          </ul>\n          <div class=\"code-box\" style=\"margin-top: 10px; font-size: 0.8rem;\">\n            Notação Chen: Elipse com círculo preenchido (&bull;) ou nome sublinhado.\n          </div>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Infográfico Metodológico</div>\n      <h2 class=\"slide-title\">Guia Visual: Representação de Atributos (Chen)</h2>\n      <p class=\"slide-subtitle\">Resumo diagramático de como desenhar cada classe de atributo no brModelo e na lousa.</p>\n\n      <div class=\"diagram-container\">\n        <svg class=\"diagram-svg\" viewBox=\"0 0 900 320\" xmlns=\"http://www.w3.org/2000/svg\">\n          <!-- Entidade Central -->\n          <rect x=\"360\" y=\"130\" width=\"180\" height=\"60\" rx=\"4\" fill=\"#ffffff\" stroke=\"#b20000\" stroke-width=\"2.5\" />\n          <text x=\"450\" y=\"166\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"16\" fill=\"#b20000\" text-anchor=\"middle\">CLIENTE</text>\n\n          <!-- 1. Identificador (Chave) - Acima à esquerda -->\n          <line x1=\"400\" y1=\"130\" x2=\"310\" y2=\"60\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <ellipse cx=\"270\" cy=\"50\" rx=\"60\" ry=\"24\" fill=\"#f8fafc\" stroke=\"#b20000\" stroke-width=\"2\" />\n          <circle cx=\"230\" cy=\"50\" r=\"4.5\" fill=\"#b20000\" />\n          <text x=\"275\" y=\"55\" font-family=\"'Inter', sans-serif\" font-weight=\"600\" font-size=\"11\" fill=\"#1e293b\" text-anchor=\"middle\">id_cliente</text>\n          <text x=\"270\" y=\"20\" font-family=\"'Inter', sans-serif\" font-size=\"10\" fill=\"#b20000\" text-anchor=\"middle\">Identificador (Chave)</text>\n\n          <!-- 2. Simples / Atômico - Acima centro -->\n          <line x1=\"450\" y1=\"130\" x2=\"450\" y2=\"60\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <ellipse cx=\"450\" cy=\"50\" rx=\"55\" ry=\"24\" fill=\"#f8fafc\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <text x=\"450\" y=\"55\" font-family=\"'Inter', sans-serif\" font-size=\"11\" fill=\"#1e293b\" text-anchor=\"middle\">nome</text>\n          <text x=\"450\" y=\"20\" font-family=\"'Inter', sans-serif\" font-size=\"10\" fill=\"#475569\" text-anchor=\"middle\">Simples (Atômico)</text>\n\n          <!-- 3. Composto - Acima à direita -->\n          <line x1=\"500\" y1=\"130\" x2=\"600\" y2=\"60\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <ellipse cx=\"630\" cy=\"50\" rx=\"55\" ry=\"24\" fill=\"#f8fafc\" stroke=\"#0284c7\" stroke-width=\"1.5\" />\n          <text x=\"630\" y=\"55\" font-family=\"'Inter', sans-serif\" font-size=\"11\" fill=\"#0284c7\" text-anchor=\"middle\">endereco</text>\n          <text x=\"630\" y=\"20\" font-family=\"'Inter', sans-serif\" font-size=\"10\" fill=\"#0284c7\" text-anchor=\"middle\">Composto</text>\n          <!-- Subatributos -->\n          <line x1=\"660\" y1=\"35\" x2=\"740\" y2=\"25\" stroke=\"#0284c7\" stroke-width=\"1\" />\n          <ellipse cx=\"780\" cy=\"25\" rx=\"35\" ry=\"16\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"1\" />\n          <text x=\"780\" y=\"29\" font-family=\"'Inter', sans-serif\" font-size=\"9\" fill=\"#334155\" text-anchor=\"middle\">rua</text>\n          <line x1=\"680\" y1=\"55\" x2=\"740\" y2=\"65\" stroke=\"#0284c7\" stroke-width=\"1\" />\n          <ellipse cx=\"780\" cy=\"65\" rx=\"35\" ry=\"16\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"1\" />\n          <text x=\"780\" y=\"69\" font-family=\"'Inter', sans-serif\" font-size=\"9\" fill=\"#334155\" text-anchor=\"middle\">cep</text>\n\n          <!-- 4. Multivalorado - Abaixo à esquerda -->\n          <line x1=\"400\" y1=\"190\" x2=\"310\" y2=\"250\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <ellipse cx=\"270\" cy=\"260\" rx=\"64\" ry=\"26\" fill=\"#f8fafc\" stroke=\"#16a34a\" stroke-width=\"1.5\" />\n          <ellipse cx=\"270\" cy=\"260\" rx=\"58\" ry=\"20\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"1.5\" />\n          <text x=\"270\" y=\"264\" font-family=\"'Inter', sans-serif\" font-size=\"11\" fill=\"#16a34a\" text-anchor=\"middle\">telefones</text>\n          <text x=\"270\" y=\"300\" font-family=\"'Inter', sans-serif\" font-size=\"10\" fill=\"#16a34a\" text-anchor=\"middle\">Multivalorado (Elipse Dupla)</text>\n\n          <!-- 5. Derivado / Calculado - Abaixo à direita -->\n          <line x1=\"500\" y1=\"190\" x2=\"600\" y2=\"250\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <ellipse cx=\"630\" cy=\"260\" rx=\"60\" ry=\"24\" fill=\"#f8fafc\" stroke=\"#d97706\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\" />\n          <text x=\"630\" y=\"264\" font-family=\"'Inter', sans-serif\" font-size=\"11\" fill=\"#d97706\" text-anchor=\"middle\">idade</text>\n          <text x=\"630\" y=\"300\" font-family=\"'Inter', sans-serif\" font-size=\"10\" fill=\"#d97706\" text-anchor=\"middle\">Derivado (Linha Tracejada)</text>\n        </svg>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Fundamentação Teórica &bull; Entidades</div>\n      <h2 class=\"slide-title\">Entidades Fortes (Regulares) vs. Entidades Fracas</h2>\n      <p class=\"slide-subtitle\">A dependência existencial e de identificação entre objetos do domínio de negócio.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Entidade Forte (Regular / Pai)</div>\n          <p class=\"card-desc\">Existe por si mesma no mundo real. Possui conjunto de atributos próprios suficientes para formar sua chave identificadora exclusiva.</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.85rem; line-height: 1.7; padding-left: 16px; margin-top: 8px;\">\n            <li><code>FUNCIONARIO</code>: Existe mesmo sem projetos ou dependentes.</li>\n            <li><code>DEPARTAMENTO</code>: Possui código próprio e autonomia organizacional.</li>\n            <li><code>CLIENTE</code>: Registro cadastral independente.</li>\n          </ul>\n          <div class=\"code-box\" style=\"margin-top: 10px; font-size: 0.8rem;\">\n            Notação Chen: Retângulo com borda simples [ ENTIDADE ].\n          </div>\n        </div>\n\n        <div class=\"card card-amber\">\n          <div class=\"card-title\">Entidade Fraca (Dependente / Filho)</div>\n          <p class=\"card-desc\">Sua existência no banco depende estritamente de uma entidade forte proprietária. Seus atributos próprios formam apenas uma <em>chave parcial</em>.</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.85rem; line-height: 1.7; padding-left: 16px; margin-top: 8px;\">\n            <li><code>DEPENDENTE</code>: Se o funcionário for demitido, o dependente perde a razão de existir no plano de saúde.</li>\n            <li>Chave completa: Formada por <code>(id_funcionario + num_dependente)</code>.</li>\n          </ul>\n          <div class=\"code-box\" style=\"margin-top: 10px; font-size: 0.8rem;\">\n            Notação Chen: Retângulo duplo [[ ENTIDADE ]] e losango duplo &lang;&lang; RELACAO &rang;&rang;.\n          </div>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Infográfico Estrutural</div>\n      <h2 class=\"slide-title\">Representação Gráfica: Entidade Fraca (Chen)</h2>\n      <p class=\"slide-subtitle\">Exemplo corporativo: Cadastro de Dependentes para plano de saúde de funcionários.</p>\n\n      <div class=\"diagram-container\">\n        <svg class=\"diagram-svg\" viewBox=\"0 0 900 280\" xmlns=\"http://www.w3.org/2000/svg\">\n          <!-- Entidade Forte: FUNCIONARIO -->\n          <rect x=\"60\" y=\"100\" width=\"200\" height=\"70\" rx=\"4\" fill=\"#f8fafc\" stroke=\"#b20000\" stroke-width=\"2.5\" />\n          <text x=\"160\" y=\"142\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"15\" fill=\"#b20000\" text-anchor=\"middle\">FUNCIONARIO</text>\n          <text x=\"160\" y=\"85\" font-family=\"'Inter', sans-serif\" font-weight=\"600\" font-size=\"11\" fill=\"#475569\" text-anchor=\"middle\">Entidade Forte</text>\n\n          <!-- Atributo Chave do Funcionario -->\n          <line x1=\"160\" y1=\"100\" x2=\"160\" y2=\"40\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <ellipse cx=\"160\" cy=\"30\" rx=\"55\" ry=\"20\" fill=\"#ffffff\" stroke=\"#b20000\" stroke-width=\"1.5\" />\n          <circle cx=\"125\" cy=\"30\" r=\"4\" fill=\"#b20000\" />\n          <text x=\"165\" y=\"34\" font-family=\"'Inter', sans-serif\" font-size=\"10\" font-weight=\"600\" fill=\"#1e293b\" text-anchor=\"middle\">matricula</text>\n\n          <!-- Relacionamento Identificador (Losango Duplo) -->\n          <line x1=\"260\" y1=\"135\" x2=\"380\" y2=\"135\" stroke=\"#475569\" stroke-width=\"2\" />\n          <text x=\"290\" y=\"125\" font-family=\"'Fira Code', monospace\" font-size=\"12\" font-weight=\"700\" fill=\"#b20000\">(1,1)</text>\n\n          <polygon points=\"450,90 520,135 450,180 380,135\" fill=\"#ffffff\" stroke=\"#d97706\" stroke-width=\"2.5\" />\n          <polygon points=\"450,98 510,135 450,172 390,135\" fill=\"none\" stroke=\"#d97706\" stroke-width=\"1.5\" />\n          <text x=\"450\" y=\"140\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"12\" fill=\"#d97706\" text-anchor=\"middle\">POSSUI</text>\n\n          <line x1=\"520\" y1=\"135\" x2=\"640\" y2=\"135\" stroke=\"#475569\" stroke-width=\"2\" />\n          <text x=\"600\" y=\"125\" font-family=\"'Fira Code', monospace\" font-size=\"12\" font-weight=\"700\" fill=\"#b20000\">(0,N)</text>\n\n          <!-- Entidade Fraca: DEPENDENTE (Retângulo Duplo) -->\n          <rect x=\"640\" y=\"100\" width=\"200\" height=\"70\" rx=\"4\" fill=\"#f8fafc\" stroke=\"#d97706\" stroke-width=\"2.5\" />\n          <rect x=\"646\" y=\"106\" width=\"188\" height=\"58\" rx=\"2\" fill=\"none\" stroke=\"#d97706\" stroke-width=\"1.5\" />\n          <text x=\"740\" y=\"142\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"15\" fill=\"#d97706\" text-anchor=\"middle\">DEPENDENTE</text>\n          <text x=\"740\" y=\"85\" font-family=\"'Inter', sans-serif\" font-weight=\"600\" font-size=\"11\" fill=\"#d97706\" text-anchor=\"middle\">Entidade Fraca</text>\n\n          <!-- Chave Parcial (Discriminador) -->\n          <line x1=\"740\" y1=\"170\" x2=\"740\" y2=\"230\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <ellipse cx=\"740\" cy=\"245\" rx=\"65\" ry=\"22\" fill=\"#ffffff\" stroke=\"#d97706\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\" />\n          <text x=\"740\" y=\"249\" font-family=\"'Inter', sans-serif\" font-size=\"10\" fill=\"#1e293b\" text-anchor=\"middle\">num_dependente</text>\n          <text x=\"740\" y=\"278\" font-family=\"'Inter', sans-serif\" font-size=\"9\" fill=\"#d97706\" text-anchor=\"middle\">Chave Parcial (Tracejada)</text>\n        </svg>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Fundamentação Teórica &bull; Cardinalidades</div>\n      <h2 class=\"slide-title\">Cardinalidades mínimas e máximas: (min, max)</h2>\n      <p class=\"slide-subtitle\">O par (mínimo, máximo) descreve a participação de cada entidade no relacionamento.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">1. Cardinalidade Mínima (Obrigatoriedade)</div>\n          <p class=\"card-desc\">Expressa a <strong>participação</strong> da entidade na relação.</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.88rem; line-height: 1.7; padding-left: 18px; margin-top: 8px;\">\n            <li><strong>0 (Zero) &bull; Participação Opcional (Parcial):</strong> A instância da entidade pode existir sem estar conectada à outra. (Ex.: Cliente que nunca comprou).</li>\n            <li><strong>1 (Um) &bull; Participação Obrigatória (Total):</strong> Cada pedido deve estar associado a pelo menos um cliente. Neste exemplo, a regra exige exatamente um.</li>\n          </ul>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">2. Cardinalidade Máxima (Multiplicidade)</div>\n          <p class=\"card-desc\">Expressa o <strong>limite superior</strong> de conexões permitidas.</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.88rem; line-height: 1.7; padding-left: 18px; margin-top: 8px;\">\n            <li><strong>1 (Um):</strong> Cada ocorrência pode se associar a no máximo uma única instância da outra entidade.</li>\n            <li><strong>N (Muitos):</strong> Não há limite pré-fixado; cada ocorrência pode se associar a dezenas, centenas ou milhares de instâncias.</li>\n          </ul>\n        </div>\n      </div>\n\n      <div class=\"card\" style=\"margin-top: 16px; padding: 14px 20px;\">\n        <strong style=\"color: var(--cps-gray-dark);\">As 4 combinações possíveis de pares:</strong>\n        <div style=\"display: flex; gap: 20px; margin-top: 8px; font-family: 'Fira Code', monospace; font-size: 0.95rem;\">\n          <span style=\"color: #0284c7;\">(0, 1): Opcional simples</span>\n          <span style=\"color: #b20000;\">(1, 1): Obrigatório exclusivo</span>\n          <span style=\"color: #16a34a;\">(0, N): Opcional múltiplo</span>\n          <span style=\"color: #d97706;\">(1, N): Obrigatório múltiplo</span>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Fundamentação Teórica &bull; Relacionamentos</div>\n      <h2 class=\"slide-title\">As Três Classes Fundamentais de Relacionamento</h2>\n      <p class=\"slide-subtitle\">A classificação formal é definida exclusivamente pela comparação das cardinalidades máximas de cada ponta.</p>\n\n      <div class=\"grid-3\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Um para Um (1:1)</div>\n          <p class=\"card-desc\">Uma instância de A associa-se a no máximo uma de B, e vice-versa.</p>\n          <div class=\"code-box\" style=\"margin-top: 8px; font-size: 0.8rem;\">\n            DEPARTAMENTO (0,1) &mdash;&lang;GERENCIA&rang;&mdash; (1,1) FUNCIONARIO\n          </div>\n          <p class=\"card-desc\" style=\"font-size: 0.82rem; margin-top: 6px;\">Exemplo: Um departamento possui no máximo 1 gerente; um funcionário só gerencia no máximo 1 departamento por vez.</p>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">Um para Muitos (1:N)</div>\n          <p class=\"card-desc\">Uma instância de A associa-se a várias de B, mas cada B conecta-se a um único A.</p>\n          <div class=\"code-box\" style=\"margin-top: 8px; font-size: 0.8rem;\">\n            CLIENTE (0,N) &mdash;&lang;REALIZA&rang;&mdash; (1,1) PEDIDO\n          </div>\n          <p class=\"card-desc\" style=\"font-size: 0.82rem; margin-top: 6px;\">Exemplo: Um cliente realiza vários pedidos ao longo dos meses; cada pedido pertence a exatamente 1 cliente.</p>\n        </div>\n\n        <div class=\"card card-green\">\n          <div class=\"card-title\">Muitos para Muitos (N:N)</div>\n          <p class=\"card-desc\">Uma instância de A associa-se a várias de B, e uma de B associa-se a várias de A.</p>\n          <div class=\"code-box\" style=\"margin-top: 8px; font-size: 0.8rem;\">\n            PEDIDO (1,N) &mdash;&lang;CONTEM&rang;&mdash; (0,N) PRODUTO\n          </div>\n          <p class=\"card-desc\" style=\"font-size: 0.82rem; margin-top: 6px;\">Exemplo: Um pedido possui múltiplos produtos; o mesmo produto aparece em múltiplos pedidos de clientes diferentes.</p>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Fundamentação Teórica &bull; Relacionamentos N:N</div>\n      <h2 class=\"slide-title\">Onde Ficam os Dados da Transação em Relações N:N?</h2>\n      <p class=\"slide-subtitle\">Um dos erros conceituais mais comuns em modelagem de dados é alocar atributos de transação no lugar errado.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">O Dilema da Modelagem Comercial</div>\n          <p class=\"card-desc\">Quando um cliente compra 3 unidades do <em>Mouse Sem Fio</em> no <em>Pedido #1024</em> a R$ 85,00 cada:</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.88rem; line-height: 1.7; padding-left: 18px; margin-top: 8px;\">\n            <li>Posso guardar <code>quantidade = 3</code> dentro de <strong>PRODUTO</strong>? <em>Não! Outro cliente no Pedido #1025 comprou 10 unidades do mesmo mouse.</em></li>\n            <li>Posso guardar <code>quantidade = 3</code> dentro de <strong>PEDIDO</strong>? <em>Não! O mesmo Pedido #1024 também tem 1 Teclado e 2 Cabos HDMI.</em></li>\n          </ul>\n        </div>\n\n        <div class=\"card card-green\">\n          <div class=\"card-title\">A Solução Semântica do MER</div>\n          <p class=\"card-desc\">A quantidade e o preço praticado não pertencem isoladamente ao Produto, nem ao Pedido. Eles caracterizam <strong>o fato da associação</strong>.</p>\n          <div class=\"code-box\" style=\"margin-top: 10px; font-size: 0.85rem; color: #16a34a;\">\n            No Modelo Conceitual, atributos que nascem da intersecção de duas entidades devem ser desenhados pendurados diretamente no LOSANGO do relacionamento!\n          </div>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Infográfico Estrutural</div>\n      <h2 class=\"slide-title\">Diagramação: Atributos no Relacionamento (Chen)</h2>\n      <p class=\"slide-subtitle\">Representação visual de atributos contextuais próprios de uma associação N:N.</p>\n\n      <div class=\"diagram-container\">\n        <svg class=\"diagram-svg\" viewBox=\"0 0 900 300\" xmlns=\"http://www.w3.org/2000/svg\">\n          <!-- Entidade PEDIDO -->\n          <rect x=\"70\" y=\"110\" width=\"180\" height=\"65\" rx=\"4\" fill=\"#ffffff\" stroke=\"#b20000\" stroke-width=\"2.5\" />\n          <text x=\"160\" y=\"150\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"16\" fill=\"#b20000\" text-anchor=\"middle\">PEDIDO</text>\n          <!-- Chave Pedido -->\n          <line x1=\"160\" y1=\"110\" x2=\"160\" y2=\"50\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <ellipse cx=\"160\" cy=\"40\" rx=\"55\" ry=\"20\" fill=\"#f8fafc\" stroke=\"#b20000\" stroke-width=\"1.5\" />\n          <circle cx=\"125\" cy=\"40\" r=\"4\" fill=\"#b20000\" />\n          <text x=\"165\" y=\"44\" font-family=\"'Inter', sans-serif\" font-size=\"10\" font-weight=\"600\" fill=\"#1e293b\" text-anchor=\"middle\">num_pedido</text>\n\n          <!-- Linha PEDIDO -> CONTEM -->\n          <line x1=\"250\" y1=\"142\" x2=\"380\" y2=\"142\" stroke=\"#475569\" stroke-width=\"2\" />\n          <text x=\"280\" y=\"132\" font-family=\"'Fira Code', monospace\" font-size=\"12\" font-weight=\"700\" fill=\"#b20000\">(1, N)</text>\n\n          <!-- Losango CONTEM -->\n          <polygon points=\"450,95 530,142 450,190 370,142\" fill=\"#f8fafc\" stroke=\"#0284c7\" stroke-width=\"2.5\" />\n          <text x=\"450\" y=\"147\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"14\" fill=\"#0284c7\" text-anchor=\"middle\">CONTEM</text>\n\n          <!-- Linha CONTEM -> PRODUTO -->\n          <line x1=\"530\" y1=\"142\" x2=\"650\" y2=\"142\" stroke=\"#475569\" stroke-width=\"2\" />\n          <text x=\"610\" y=\"132\" font-family=\"'Fira Code', monospace\" font-size=\"12\" font-weight=\"700\" fill=\"#b20000\">(0, N)</text>\n\n          <!-- Entidade PRODUTO -->\n          <rect x=\"650\" y=\"110\" width=\"180\" height=\"65\" rx=\"4\" fill=\"#ffffff\" stroke=\"#b20000\" stroke-width=\"2.5\" />\n          <text x=\"740\" y=\"150\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"16\" fill=\"#b20000\" text-anchor=\"middle\">PRODUTO</text>\n          <!-- Chave Produto -->\n          <line x1=\"740\" y1=\"110\" x2=\"740\" y2=\"50\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <ellipse cx=\"740\" cy=\"40\" rx=\"55\" ry=\"20\" fill=\"#f8fafc\" stroke=\"#b20000\" stroke-width=\"1.5\" />\n          <circle cx=\"705\" cy=\"40\" r=\"4\" fill=\"#b20000\" />\n          <text x=\"745\" y=\"44\" font-family=\"'Inter', sans-serif\" font-size=\"10\" font-weight=\"600\" fill=\"#1e293b\" text-anchor=\"middle\">cod_produto</text>\n\n          <!-- Atributos do Losango: quantidade e preco_venda -->\n          <line x1=\"420\" y1=\"180\" x2=\"360\" y2=\"240\" stroke=\"#0284c7\" stroke-width=\"1.5\" />\n          <ellipse cx=\"340\" cy=\"255\" rx=\"55\" ry=\"22\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"1.5\" />\n          <text x=\"340\" y=\"259\" font-family=\"'Inter', sans-serif\" font-size=\"10\" font-weight=\"600\" fill=\"#0284c7\" text-anchor=\"middle\">quantidade</text>\n\n          <line x1=\"480\" y1=\"180\" x2=\"540\" y2=\"240\" stroke=\"#0284c7\" stroke-width=\"1.5\" />\n          <ellipse cx=\"560\" cy=\"255\" rx=\"60\" ry=\"22\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"1.5\" />\n          <text x=\"560\" y=\"259\" font-family=\"'Inter', sans-serif\" font-size=\"10\" font-weight=\"600\" fill=\"#0284c7\" text-anchor=\"middle\">preco_venda</text>\n        </svg>\n      </div>\n\n      <div class=\"callout callout-blue\" style=\"margin-top: 10px;\">\n        <strong>Conexão com as próximas aulas:</strong> No modelo relacional e na implementação SQL no Oracle, este losango com atributos próprios dará origem à tabela associativa <code>ITENS_PEDIDO</code>.\n      </div>\n    </section>",
  "<section class=\"slide slide-cover\">\n      <div class=\"section-tag\">Bloco 3 &bull; Transição para o Laboratório de Informática</div>\n      <h2 class=\"cover-title\" style=\"font-size: 2.5rem;\">brModelo: Ferramenta CASE para Modelagem</h2>\n      <p class=\"slide-subtitle\" style=\"max-width: 780px;\">\n        2 Horas de Prática Guiada: Da teoria na lousa para a diagramação estruturada no software de modelagem relacional.\n      </p>\n      <div class=\"callout\" style=\"max-width: 760px; text-align: left;\">\n        <strong>Instrução aos alunos:</strong> Ocupem seus postos no laboratório, inicializem o ambiente Windows e abram o software <strong>brModelo</strong> (ou o <strong>brModelo Web</strong> no navegador).\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Ambiente de Laboratório &bull; Ferramenta</div>\n      <h2 class=\"slide-title\">Conhecendo a Interface Operacional do brModelo</h2>\n      <p class=\"slide-subtitle\">Três áreas funcionais essenciais compõem a área de trabalho da ferramenta.</p>\n\n      <div class=\"grid-3\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">1. Barra de Componentes</div>\n          <p class=\"card-desc\">Barra superior/lateral contendo os objetos conceituais fundamentais:</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.82rem; line-height: 1.6; padding-left: 16px; margin-top: 8px;\">\n            <li><strong>Entidade</strong> (ícone de retângulo).</li>\n            <li><strong>Relacionamento</strong> (ícone de losango).</li>\n            <li><strong>Atributo</strong> (ícone de elipse/conector).</li>\n            <li><strong>Especialização / Generalização</strong> (ícone de triângulo).</li>\n            <li><strong>Conector de Ligação</strong>.</li>\n          </ul>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">2. Canvas de Modelagem</div>\n          <p class=\"card-desc\">Área de trabalho livre com malha quadriculada para posicionamento espacial limpo dos diagramas.</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.82rem; line-height: 1.6; padding-left: 16px; margin-top: 8px;\">\n            <li>Permite arrastar, alinhar e redimensionar nós.</li>\n            <li>Facilita leitura lógica evitando cruzamento de linhas.</li>\n          </ul>\n        </div>\n\n        <div class=\"card card-green\">\n          <div class=\"card-title\">3. Painel de Propriedades</div>\n          <p class=\"card-desc\">Painel lateral onde configuramos os detalhes do elemento selecionado:</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.82rem; line-height: 1.6; padding-left: 16px; margin-top: 8px;\">\n            <li>Nome do objeto (usar CAIXA ALTA).</li>\n            <li>Checkboxes: <em>Identificador</em>, <em>Multivalorado</em>, <em>Opcional</em>.</li>\n            <li>Configuração de cardinalidade mínima e máxima.</li>\n          </ul>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Guia Passo a Passo &bull; Operação</div>\n      <h2 class=\"slide-title\">Fluxo Padronizado de Construção no brModelo</h2>\n      <p class=\"slide-subtitle\">Siga este roteiro sistemático em quatro etapas para desenhar sem travamentos.</p>\n\n      <div class=\"stepper\">\n        <div class=\"step-item\">\n          <div class=\"step-circle\">1</div>\n          <div class=\"step-title\">Criar Entidade</div>\n          <div class=\"step-desc\">Clique no Retângulo &rarr; Clique no Canvas &rarr; Defina o Nome</div>\n        </div>\n        <div class=\"step-item\">\n          <div class=\"step-circle\">2</div>\n          <div class=\"step-title\">Adicionar Atributos</div>\n          <div class=\"step-desc\">Clique no Atributo &rarr; Conecte à Entidade &rarr; Marque Identificador</div>\n        </div>\n        <div class=\"step-item\">\n          <div class=\"step-circle\">3</div>\n          <div class=\"step-title\">Criar Relação</div>\n          <div class=\"step-desc\">Clique no Losango &rarr; Posicione entre as Entidades &rarr; Conecte</div>\n        </div>\n        <div class=\"step-item\">\n          <div class=\"step-circle\">4</div>\n          <div class=\"step-title\">Definir Cardinalidade</div>\n          <div class=\"step-desc\">Clique nas linhas de ligação &rarr; Ajuste (min, max)</div>\n        </div>\n      </div>\n\n      <div class=\"callout callout-blue\" style=\"margin-top: 24px;\">\n        <strong>Dica de Produtividade no Lab:</strong> Sempre dê nomes no singular e em MAIÚSCULAS para as entidades (ex.: <code>CLIENTE</code>, <code>PRODUTO</code>, <code>PEDIDO</code>) e em minúsculas para os atributos (ex.: <code>id_cliente</code>, <code>preco_venda</code>).\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Guia Passo a Passo &bull; Operação</div>\n      <h2 class=\"slide-title\">Configurando Cardinalidades no brModelo</h2>\n      <p class=\"slide-subtitle\">Como garantir que a leitura gráfica corresponda à regra semântica de negócio.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Como aplicar no brModelo</div>\n          <ol style=\"color: var(--cps-gray-medium); font-size: 0.88rem; line-height: 1.8; padding-left: 20px;\">\n            <li>Ligue o losango do relacionamento à entidade usando a ferramenta <strong>Conexão</strong>.</li>\n            <li>Clique diretamente sobre a linha ou sobre o rótulo de cardinalidade gerado junto à entidade.</li>\n            <li>No campo de propriedades, selecione o par correspondente: <code>(0,1)</code>, <code>(1,1)</code>, <code>(0,n)</code> ou <code>(1,n)</code>.</li>\n          </ol>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">A Regra da Leitura Direcional</div>\n          <p class=\"card-desc\">Para não errar a ponta da cardinalidade, faça mentalmente a pergunta em voz alta:</p>\n          <div class=\"code-box\" style=\"margin-top: 8px; font-size: 0.85rem;\">\n            \"Um CLIENTE realiza quantos PEDIDOS?\"<br>\n            &rarr; No mínimo 0, no máximo N.<br>\n            <strong>Portanto, o rótulo (0,N) fica no lado do PEDIDO!</strong>\n          </div>\n          <div class=\"code-box\" style=\"margin-top: 8px; font-size: 0.85rem;\">\n            \"Um PEDIDO pertence a quantos CLIENTES?\"<br>\n            &rarr; No mínimo 1, no máximo 1.<br>\n            <strong>Portanto, o rótulo (1,1) fica no lado do CLIENTE!</strong>\n          </div>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide slide-cover\">\n      <div class=\"section-tag\">Bloco 4 &bull; Prática Guiada no Laboratório</div>\n      <h2 class=\"cover-title\" style=\"font-size: 2.5rem;\">Estudo de Caso: \"Controle Comercial Sorocaba\"</h2>\n      <p class=\"slide-subtitle\" style=\"max-width: 800px;\">\n        Modelagem completa e assistida no brModelo: construindo um esquema com 4 entidades, relacionamentos 1:N, N:N, atributos multivalorados e atributos no relacionamento.\n      </p>\n      <div class=\"callout\" style=\"max-width: 760px; text-align: left;\">\n        <strong>Condução da prática:</strong> O professor projetará a tela executando cada etapa enquanto os alunos acompanham simultaneamente em suas estações no laboratório.\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Prática Guiada &bull; Requisitos</div>\n      <h2 class=\"slide-title\">Especificação de Requisitos: Comercial Sorocaba</h2>\n      <p class=\"slide-subtitle\">Analise os 5 requisitos corporativos para iniciar a modelagem no brModelo.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Produtos e Categorias</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.86rem; line-height: 1.7; padding-left: 16px;\">\n            <li><strong>Produtos:</strong> código (identificador), nome, preço de venda e quantidade em estoque.</li>\n            <li><strong>Categorias:</strong> código (identificador) e nome da categoria (ex.: Informática, Eletrônicos).</li>\n            <li><strong>Regra:</strong> Todo produto pertence obrigatoriamente a uma única categoria; uma categoria pode ter nenhum ou vários produtos cadastrados.</li>\n          </ul>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">Clientes, Pedidos e Itens Vendidos</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.86rem; line-height: 1.7; padding-left: 16px;\">\n            <li><strong>Clientes:</strong> código (identificador), nome, CPF, e-mail e múltiplos <strong>telefones</strong> para contato.</li>\n            <li><strong>Pedidos:</strong> número do pedido (identificador), data/hora de emissão e valor total.</li>\n            <li><strong>Regra do Pedido:</strong> Um pedido deve pertencer obrigatoriamente a um único cliente.</li>\n            <li><strong>Regra dos Itens:</strong> Um pedido contém um ou vários produtos; em cada item vendido, registra-se a <strong>quantidade</strong> e o <strong>preço praticado no momento da venda</strong>.</li>\n          </ul>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Prática Guiada &bull; Passo 1 de 3</div>\n      <h2 class=\"slide-title\">Passo 1: Modelando CATEGORIA e PRODUTO (1:N)</h2>\n      <p class=\"slide-subtitle\">Cadastre as entidades e defina o relacionamento entre categoria e produto.</p>\n\n      <div class=\"card card-red\" style=\"padding: 20px;\">\n        <div class=\"card-title\">Ações no brModelo:</div>\n        <ol style=\"color: var(--cps-gray-dark); font-size: 0.95rem; line-height: 1.8; padding-left: 20px;\">\n          <li>Crie a entidade <code>CATEGORIA</code> com os atributos: <strong>id_categoria</strong> (marque <em>Identificador</em>) e <strong>nome_categoria</strong>.</li>\n          <li>Crie a entidade <code>PRODUTO</code> com: <strong>id_produto</strong> (marque <em>Identificador</em>), <strong>nome</strong>, <strong>preco_tabela</strong> e <strong>qtd_estoque</strong>.</li>\n          <li>Adicione o relacionamento <code>PERTENCE_A</code> ligando as duas entidades.</li>\n          <li>Configure as cardinalidades:\n            <ul style=\"padding-left: 18px; margin-top: 6px;\">\n              <li>Cardinalidade de PRODUTO: <strong>(1, 1)</strong> &bull; <em>\"Todo produto pertence a 1 categoria.\"</em></li>\n              <li>Cardinalidade de CATEGORIA: <strong>(0, n)</strong> &bull; <em>\"Uma categoria pode ter 0 ou vários produtos.\"</em></li>\n            </ul>\n          </li>\n        </ol>\n      </div>\n\n      <div class=\"code-box\" style=\"margin-top: 14px; font-size: 0.85rem;\">\n        Estrutura resultante: CATEGORIA (0, n) &mdash;&lang; PERTENCE_A &rang;&mdash; (1, 1) PRODUTO\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Prática Guiada &bull; Passo 2 de 3</div>\n      <h2 class=\"slide-title\">Passo 2: Modelando CLIENTE, TELEFONE e PEDIDO</h2>\n      <p class=\"slide-subtitle\">Inserindo atributo multivalorado e associação de faturamento.</p>\n\n      <div class=\"card card-blue\" style=\"padding: 20px;\">\n        <div class=\"card-title\">Ações no brModelo:</div>\n        <ol style=\"color: var(--cps-gray-dark); font-size: 0.95rem; line-height: 1.8; padding-left: 20px;\">\n          <li>Crie a entidade <code>CLIENTE</code> com: <strong>id_cliente</strong> (<em>Identificador</em>), <strong>nome</strong>, <strong>cpf</strong> e <strong>email</strong>.</li>\n          <li>Crie o atributo <strong>telefones</strong> conectado a <code>CLIENTE</code> e marque no painel de propriedades a opção <strong>Multivalorado</strong> (elipse dupla).</li>\n          <li>Crie <code>PEDIDO</code> com <strong>num_pedido</strong> (identificador), <strong>data_emissao</strong> e <strong>valor_total</strong> (derivado da soma dos itens, se essa for a regra adotada).</li>\n          <li>Ligue <code>CLIENTE</code> a <code>PEDIDO</code> com o relacionamento <code>REALIZA</code>.</li>\n          <li>Configure as cardinalidades:\n            <ul style=\"padding-left: 18px; margin-top: 6px;\">\n              <li>Próximo a <code>CLIENTE</code>: <strong>(1, 1)</strong> &bull; <em>\"O pedido pertence a 1 cliente.\"</em></li>\n              <li>Próximo a <code>PEDIDO</code>: <strong>(0, n)</strong> &bull; <em>\"O cliente realiza 0 ou N pedidos.\"</em></li>\n            </ul>\n          </li>\n        </ol>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Prática Guiada &bull; Passo 3 de 3</div>\n      <h2 class=\"slide-title\">Passo 3: Conexão N:N e Atributos no Losango CONTEM</h2>\n      <p class=\"slide-subtitle\">Modele quais produtos aparecem em cada pedido e os dados específicos de cada item.</p>\n\n      <div class=\"card card-green\" style=\"padding: 20px;\">\n        <div class=\"card-title\">Ações no brModelo:</div>\n        <ol style=\"color: var(--cps-gray-dark); font-size: 0.95rem; line-height: 1.8; padding-left: 20px;\">\n          <li>Adicione o relacionamento <code>CONTEM</code> entre <code>PEDIDO</code> e <code>PRODUTO</code>.</li>\n          <li>Configure as cardinalidades:\n            <ul style=\"padding-left: 18px; margin-top: 4px;\">\n              <li>Próximo a <code>PEDIDO</code>: <strong>(0, n)</strong> &bull; <em>\"Um produto pode constar em 0 ou vários pedidos.\"</em></li>\n              <li>Próximo a <code>PRODUTO</code>: <strong>(1, n)</strong> &bull; <em>\"Um pedido contém obrigatoriamente no mínimo 1 e no máximo N produtos.\"</em></li>\n            </ul>\n          </li>\n          <li>Use a ferramenta <em>Atributo</em> e conecte os atributos de cada item ao losango <strong>CONTEM</strong>.</li>\n          <li>Adicione os atributos de transação:\n            <ul style=\"padding-left: 18px; margin-top: 4px;\">\n              <li><code>quantidade_vendida</code> (quantidade daquele item específico)</li>\n              <li><code>preco_praticado</code> (preço real com eventual desconto na hora da venda)</li>\n            </ul>\n          </li>\n        </ol>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Artefato de Modelagem Final</div>\n      <h2 class=\"slide-title\">Diagrama Conceitual Completo: Comercial Sorocaba</h2>\n      <p class=\"slide-subtitle\">Visão integrada das 4 entidades e seus relacionamentos no brModelo.</p>\n\n      <div class=\"diagram-container\">\n        <svg class=\"diagram-svg\" viewBox=\"0 0 920 330\" xmlns=\"http://www.w3.org/2000/svg\">\n          <!-- CATEGORIA -->\n          <rect x=\"30\" y=\"50\" width=\"140\" height=\"50\" rx=\"3\" fill=\"#ffffff\" stroke=\"#b20000\" stroke-width=\"2\" />\n          <text x=\"100\" y=\"80\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"12\" fill=\"#b20000\" text-anchor=\"middle\">CATEGORIA</text>\n          <line x1=\"170\" y1=\"75\" x2=\"250\" y2=\"75\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <text x=\"235\" y=\"65\" font-family=\"'Fira Code', monospace\" font-size=\"10\" fill=\"#b20000\">(0,n)</text>\n\n          <!-- PERTENCE_A -->\n          <polygon points=\"280,55 310,75 280,95 250,75\" fill=\"#f8fafc\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <text x=\"280\" y=\"78\" font-family=\"'Inter', sans-serif\" font-size=\"8\" font-weight=\"600\" fill=\"#334155\" text-anchor=\"middle\">PERTENCE</text>\n          <line x1=\"310\" y1=\"75\" x2=\"390\" y2=\"75\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <text x=\"320\" y=\"65\" font-family=\"'Fira Code', monospace\" font-size=\"10\" fill=\"#b20000\">(1,1)</text>\n\n          <!-- PRODUTO -->\n          <rect x=\"390\" y=\"50\" width=\"140\" height=\"50\" rx=\"3\" fill=\"#ffffff\" stroke=\"#b20000\" stroke-width=\"2\" />\n          <text x=\"460\" y=\"80\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"13\" fill=\"#b20000\" text-anchor=\"middle\">PRODUTO</text>\n\n          <!-- Conexao PRODUTO -> CONTEM (descendo) -->\n          <line x1=\"460\" y1=\"100\" x2=\"460\" y2=\"180\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <text x=\"475\" y=\"125\" font-family=\"'Fira Code', monospace\" font-size=\"10\" fill=\"#b20000\">(0,n)</text>\n\n          <!-- CONTEM (losango central com atributos) -->\n          <polygon points=\"460,180 500,205 460,230 420,205\" fill=\"#f8fafc\" stroke=\"#0284c7\" stroke-width=\"2\" />\n          <text x=\"460\" y=\"209\" font-family=\"'Inter', sans-serif\" font-size=\"9\" font-weight=\"700\" fill=\"#0284c7\" text-anchor=\"middle\">CONTEM</text>\n\n          <!-- Atributos do CONTEM -->\n          <line x1=\"420\" y1=\"210\" x2=\"370\" y2=\"240\" stroke=\"#0284c7\" stroke-width=\"1.2\" />\n          <ellipse cx=\"340\" cy=\"250\" rx=\"42\" ry=\"16\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"1.2\" />\n          <text x=\"340\" y=\"253\" font-family=\"'Inter', sans-serif\" font-size=\"8\" fill=\"#0284c7\" text-anchor=\"middle\">quantidade</text>\n          <line x1=\"500\" y1=\"210\" x2=\"550\" y2=\"240\" stroke=\"#0284c7\" stroke-width=\"1.2\" />\n          <ellipse cx=\"585\" cy=\"250\" rx=\"46\" ry=\"16\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"1.2\" />\n          <text x=\"585\" y=\"253\" font-family=\"'Inter', sans-serif\" font-size=\"8\" fill=\"#0284c7\" text-anchor=\"middle\">preco_praticado</text>\n\n          <!-- PEDIDO -->\n          <line x1=\"460\" y1=\"230\" x2=\"460\" y2=\"270\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <text x=\"475\" y=\"260\" font-family=\"'Fira Code', monospace\" font-size=\"10\" fill=\"#b20000\">(1,n)</text>\n          <rect x=\"390\" y=\"270\" width=\"140\" height=\"48\" rx=\"3\" fill=\"#ffffff\" stroke=\"#b20000\" stroke-width=\"2\" />\n          <text x=\"460\" y=\"299\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"13\" fill=\"#b20000\" text-anchor=\"middle\">PEDIDO</text>\n\n          <!-- Linha PEDIDO -> REALIZA -> CLIENTE -->\n          <line x1=\"530\" y1=\"294\" x2=\"620\" y2=\"294\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <text x=\"540\" y=\"284\" font-family=\"'Fira Code', monospace\" font-size=\"10\" fill=\"#b20000\">(1,1)</text>\n          <polygon points=\"650,274 680,294 650,314 620,294\" fill=\"#f8fafc\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <text x=\"650\" y=\"298\" font-family=\"'Inter', sans-serif\" font-size=\"9\" font-weight=\"600\" fill=\"#334155\" text-anchor=\"middle\">REALIZA</text>\n          <line x1=\"680\" y1=\"294\" x2=\"760\" y2=\"294\" stroke=\"#475569\" stroke-width=\"1.5\" />\n          <text x=\"740\" y=\"284\" font-family=\"'Fira Code', monospace\" font-size=\"10\" fill=\"#b20000\">(0,n)</text>\n\n          <!-- CLIENTE -->\n          <rect x=\"760\" y=\"270\" width=\"140\" height=\"48\" rx=\"3\" fill=\"#ffffff\" stroke=\"#b20000\" stroke-width=\"2\" />\n          <text x=\"830\" y=\"299\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"13\" fill=\"#b20000\" text-anchor=\"middle\">CLIENTE</text>\n\n          <!-- Multivalorado Telefones -->\n          <line x1=\"830\" y1=\"270\" x2=\"830\" y2=\"225\" stroke=\"#16a34a\" stroke-width=\"1.2\" />\n          <ellipse cx=\"830\" cy=\"205\" rx=\"46\" ry=\"18\" fill=\"#f8fafc\" stroke=\"#16a34a\" stroke-width=\"1.2\" />\n          <ellipse cx=\"830\" cy=\"205\" rx=\"40\" ry=\"14\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"1.2\" />\n          <text x=\"830\" y=\"209\" font-family=\"'Inter', sans-serif\" font-size=\"8\" fill=\"#16a34a\" text-anchor=\"middle\">telefones</text>\n        </svg>\n      </div>\n\n      <div class=\"callout callout-green\" style=\"margin-top: 8px;\">\n        <strong>Resultado:</strong> Modelo conceitual completo, revisado para a etapa de mapeamento relacional. Salvem o arquivo <code>comercial_sorocaba.brM3</code> em suas pastas de trabalho!\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Bloco 5 &bull; Atividade Prática no Laboratório</div>\n      <h2 class=\"slide-title\">Desafio Autônomo: \"Oficina Mecânica Sorocaba\"</h2>\n      <p class=\"slide-subtitle\">Trabalho individual ou em duplas no brModelo durante os próximos 40 minutos com atendimento circulante.</p>\n\n      <div class=\"card card-red\" style=\"padding: 22px; font-size: 1.02rem; line-height: 1.8;\">\n        <p>\n          <em>\"Uma oficina mecânica necessita gerenciar seus atendimentos. A oficina cadastra <strong>Clientes</strong> (código, nome, CPF e telefones) e seus <strong>Veículos</strong> (placa, marca, modelo e ano). Um cliente pode possuir múltiplos veículos, mas cada veículo pertence a exatamente um cliente.\"</em>\n        </p>\n        <p style=\"margin-top: 10px;\">\n          <em>\"Quando o veículo entra na oficina, abre-se uma <strong>Ordem de Serviço</strong> (número da OS, data de abertura, status e valor total). Uma OS é aberta para um único veículo.\"</em>\n        </p>\n        <p style=\"margin-top: 10px;\">\n          <em>\"Na OS, são executados diversos <strong>Serviços</strong> (código, descrição e preço da hora). Para cada serviço realizado naquela OS específica, anota-se a <strong>quantidade de horas trabalhadas</strong>.\"</em>\n        </p>\n      </div>\n\n      <div class=\"grid-2\" style=\"margin-top: 16px;\">\n        <div class=\"card\" style=\"padding: 12px;\">\n          <strong style=\"color: var(--cps-red);\">Entregável:</strong> Arquivo do brModelo com as entidades, atributos identificadores e relacionamento N:N com atributos no losango.\n        </div>\n        <div class=\"card\" style=\"padding: 12px;\">\n          <strong style=\"color: var(--tech-blue);\">Atendimento:</strong> Tire dúvidas levantando a mão no laboratório ou chamando o professor à sua bancada.\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Boas Práticas &bull; Checklist de Validação</div>\n      <h2 class=\"slide-title\">Checklist: Os 5 Erros Mais Comuns de Iniciantes</h2>\n      <p class=\"slide-subtitle\">Antes de salvar e enviar seu modelo conceitual, faça uma auditoria rápida nestes 5 pontos:</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">1. Atributo Órfão ou Desconectado</div>\n          <p class=\"card-desc\">Todo atributo precisa estar ligado obrigatoriamente a uma entidade ou a um losango de relacionamento. Não deixe elipses soltas no canvas.</p>\n        </div>\n\n        <div class=\"card card-red\">\n          <div class=\"card-title\">2. Entidade Forte sem Atributo Identificador</div>\n          <p class=\"card-desc\">Toda entidade forte <strong>exige pelo menos um atributo identificador</strong> marcado (círculo preenchido). Sem isso, não há chave primária!</p>\n        </div>\n\n        <div class=\"card card-amber\">\n          <div class=\"card-title\">3. Inversão de Cardinalidade Mínima/Máxima</div>\n          <p class=\"card-desc\">Confira se o par está como <code>(min, max)</code> e nunca <code>(max, min)</code>. O menor valor sempre vem antes da vírgula.</p>\n        </div>\n\n        <div class=\"card card-amber\">\n          <div class=\"card-title\">4. Ligar Relacionamento a outro Relacionamento</div>\n          <p class=\"card-desc\">No Modelo Entidade-Relacionamento clássico, losangos ligam-se <strong>apenas a retângulos de entidades</strong>. Nunca conecte losango a losango!</p>\n        </div>\n      </div>\n\n      <div class=\"callout callout-blue\" style=\"margin-top: 16px;\">\n        <strong>5. O Erro Clássico de Atributos de Transação:</strong> Lembre-se: <em>quantidade</em> e <em>preço praticado</em> na venda ficam no <strong>losango</strong> do relacionamento N:N, nunca dentro da entidade Produto!\n      </div>\n    </section>",
  "<section class=\"slide slide-cover\">\n      <div class=\"section-tag\">Encerramento &bull; Síntese da Aula 02</div>\n      <h2 class=\"cover-title\" style=\"font-size: 2.5rem;\">Síntese da Aula 02 &amp; Próximos Passos</h2>\n      <p class=\"slide-subtitle\" style=\"max-width: 780px; margin-bottom: 24px;\">\n        Revisamos os elementos do modelo Entidade-Relacionamento e aplicamos esses conceitos no brModelo.\n      </p>\n\n      <div class=\"grid-2\" style=\"max-width: 820px; text-align: left; margin: 0 auto 24px auto;\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Conteúdos desta aula:</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.88rem; line-height: 1.7; padding-left: 18px;\">\n            <li>Correção detalhada do caso <em>Biblioteca Saber</em>.</li>\n            <li>Classificação de atributos e identificação de entidades fracas.</li>\n            <li>Definição de cardinalidades mínimas e máximas.</li>\n            <li>Atributos de transação no losango em relações N:N.</li>\n            <li>Desenho e validação de diagramas DER no <strong>brModelo</strong>.</li>\n          </ul>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">Próximo Encontro (Aula 03 &bull; Sábado Letivo 2):</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.88rem; line-height: 1.7; padding-left: 18px;\">\n            <li><strong>DER Avançado:</strong> Especialização e Generalização (Herança de atributos).</li>\n            <li><strong>Auto-relacionamentos:</strong> Entidade associando-se a si mesma (ex.: Funcionário supervisiona Funcionário).</li>\n            <li><strong>Entidades Associativas:</strong> Resolução de N:N avançados.</li>\n          </ul>\n        </div>\n      </div>\n\n      <div style=\"color: var(--cps-gray-medium); font-size: 0.85rem;\">\n        Faculdade de Tecnologia de Sorocaba — Fatec Sorocaba &bull; Centro Paula Souza\n      </div>\n    </section>"
]
};
